  const nav = active => { const primary = links.slice(0, 5), operations = links.slice(5, 7), content = links.slice(7, 9), system = links.slice(9); return `<header class="mpa-topbar admin-topbar"><div class="admin-topbar-inner"><a class="mpa-brand admin-brand" href="dashboard.html" aria-label="AP Service ศูนย์ควบคุมหลังบ้าน"><span class="admin-brand-mark">AP</span><span><b>AP Service</b><small>ศูนย์ควบคุม</small></span></a><nav class="mpa-nav admin-nav" aria-label="เมนูผู้ดูแลระบบ"><div class="admin-nav-primary">${primary.map(([key,label,iconKey]) => navLink(key,label,iconKey,active)).join('')}</div><details class="admin-nav-more"><summary title="เมนูเพิ่มเติม" aria-label="เมนูเพิ่มเติม">${icon('more')}<span>เพิ่มเติม</span></summary><div class="admin-nav-popover">${navGroup('การปฏิบัติงาน', operations, active)}${navGroup('เนื้อหาและสื่อ', content, active)}${navGroup('ระบบ', system, active)}<section class="admin-nav-group admin-nav-group-legacy" aria-label="ฟังก์ชันเพิ่มเติม"><p>ฟังก์ชันเพิ่มเติม</p>${legacyLinks.map(([key,label]) => `<a class="admin-nav-legacy" href="operations.html?feature=${encodeURIComponent(key)}">${icon('legacy')}<span>${h(label)}</span></a>`).join('')}</section></div></details><a class="admin-account-link" href="settings.html" title="บัญชีและตั้งค่ากลาง" aria-label="บัญชีและตั้งค่ากลาง">${icon('account')}<span>บัญชี</span></a></nav></div></header>`; };
