        const rawPath = String(review.slip_path || ''); const path = rawPath.replace(/^payment-slips\//, ''); if (!path) throw new Error('ไม่พบตำแหน่งจัดเก็บสลิป');
        const session = await M.auth.refreshSession(false); if (!session?.access_token) throw new Error('เซสชันหมดอายุ กรุณาเข้าสู่ระบบใหม่');
