      const rulesFor = service => ({ ...testDefaults[service], ...((storedRules?.[service] && typeof storedRules[service] === 'object') ? storedRules[service] : (storedRules?.base_fee !== undefined ? storedRules : {})) }); const pricingFields = [['base_fee', 'ค่าส่งเริ่มต้น (บาท)', '0.01'], ['included_km', 'ระยะทางที่รวมในราคา (กม.)', '0.1'], ['per_km_fee', 'ค่าส่งต่อกม.เกิน (บาท)', '0.01'], ['zone_multiplier', 'ตัวคูณราคาโซน', '0.1'], ['service_fee', 'ค่าบริการแพลตฟอร์ม (บาท)', '0.01']]; const pricingForm = (service, label) => { const values = rulesFor(service); return `<section class="mpa-card" style="box-shadow:none;border:1px solid var(--ap-line);margin:16px 0"><h3 style="margin-top:0">${h(label)}</h3><div class="mpa-grid" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr))">${pricingFields.map(([key, text, step]) => `<div class="mpa-field"><label>${h(text)}</label><input data-rule="${service}:${key}" type="number" min="${key === 'zone_multiplier' ? '0.01' : '0'}" step="${step}" value="${h(values[key])}"></div>`).join('')}</div></section>`; };
